package com.onlinelearning.service.impl;
import com.onlinelearning.entity.*; import com.onlinelearning.exception.*; import com.onlinelearning.repository.*; import com.onlinelearning.service.*; import lombok.*; import org.springframework.http.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*;
@Service @RequiredArgsConstructor @Transactional public class CourseServiceImpl implements CourseService { private final CourseRepository courses; private final UserRepository users; private final AuditLogRepository auditLogs; private final CourseSubmissionReadinessService readiness;
 public Course submit(Long id,String email){return transition(id,email,CourseStatus.DRAFT);}
 private Course transition(Long id,String email,CourseStatus expected){Course c=owned(id,email);if(c.getStatus()!=expected)throw new ApiException(HttpStatus.CONFLICT,"Trạng thái khóa học không cho phép thao tác này");readiness.requireReady(c);c.setStatus(CourseStatus.PENDING_REVIEW);record(c,c.getExpert(),expected==CourseStatus.DRAFT?"COURSE_SUBMITTED":"COURSE_RESUBMITTED",null);return c;}
 public Course approve(Long id,String email){User manager=manager(email);Course c=pending(id);c.setStatus(CourseStatus.PUBLISHED);c.setReviewedBy(manager);c.setRejectionReason(null);record(c,manager,"COURSE_APPROVED",null);return c;}
 public Course reject(Long id,String email,String reason){User manager=manager(email);if(reason==null||reason.isBlank()||reason.length()>255)throw new ApiException(HttpStatus.BAD_REQUEST,"Lý do từ chối phải có từ 1 đến 255 ký tự");Course c=pending(id);c.setStatus(CourseStatus.REJECTED);c.setReviewedBy(manager);c.setRejectionReason(reason.trim());record(c,manager,"COURSE_REJECTED",reason.trim());return c;}
 private User manager(String email){User actor=user(email);if(actor.getRoles().stream().noneMatch(r->"MANAGER".equals(r.getCode())))throw new ApiException(HttpStatus.FORBIDDEN,"Chỉ Manager được xét duyệt khóa học");return actor;}
 private void record(Course c,User actor,String action,String reason){AuditLog log=new AuditLog();log.setActor(actor);log.setAction(action);log.setTargetType("COURSE");log.setTargetId(c.getId().toString());log.setMetadata(reason);log.setOccurredAt(java.time.Instant.now());auditLogs.save(log);}
 public Course resubmit(Long id,String email){return transition(id,email,CourseStatus.REJECTED);} private Course owned(Long id,String email){Course c=courses.findForUpdate(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Course not found"));if(!c.getExpert().getEmail().equalsIgnoreCase(email))throw new ApiException(HttpStatus.FORBIDDEN,"You can only manage your own courses");return c;} private Course pending(Long id){Course c=courses.findForUpdate(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Course not found"));if(c.getStatus()!=CourseStatus.PENDING_REVIEW)throw new ApiException(HttpStatus.CONFLICT,"Course is not pending review");return c;} private User user(String email){return users.findByEmailIgnoreCase(email).orElseThrow();}}
